// Format a failed execution into one Telegram alert.
// This workflow runs automatically when any workflow that selects it as
// its error workflow fails (Settings -> Error Workflow).

const payload = $input.first().json || {};
const execution = payload.execution || {};
const workflow = payload.workflow || {};

const errorMessage = execution.error?.message || 'Unknown error';
const errorNode = execution.error?.node?.name || 'Unknown node';
const workflowName = workflow.name || 'Unknown workflow';
const executionId = execution.id || 'N/A';

// Best-effort: recover the lead's phone from the failed execution so the
// operator can follow up manually even when the automation broke.
let phone = 'No disponible';
try {
  const runData = execution.data?.resultData?.runData || {};
  const normalized = runData['Set / Normalize Input']?.[0]?.data?.main?.[0]?.[0]?.json;
  if (normalized?.phone) {
    phone = normalized.phone;
  } else {
    const webhook = runData['Webhook Trigger']?.[0]?.data?.main?.[0]?.[0]?.json;
    phone = webhook?.body?.phone
      || webhook?.body?.data?.key?.remoteJid?.replace('@s.whatsapp.net', '')
      || phone;
  }
} catch (error) {
  phone = 'Error extrayendo número';
}

const mensaje = `🚨 *ERROR EN WORKFLOW*\n\n*Workflow:* ${workflowName}\n*Nodo que falló:* ${errorNode}\n*Error:* ${String(errorMessage).substring(0, 500)}\n*Contacto:* ${phone}\n*Execution ID:* ${executionId}\n*Timestamp:* ${new Date().toISOString()}\n\n_Revisar en n8n → Executions para más detalles_`;

return [{
  json: {
    mensaje,
  },
}];
